SELECT quantity_bucket, store_id, unique_products, total_count FROM (SELECT CASE WHEN quantity >= 188 THEN 'high' WHEN quantity >= 43 THEN 'mid' ELSE 'low' END quantity_bucket, store_id, COUNT(DISTINCT quantity) unique_products, COUNT(*) total_count FROM inventory GROUP BY CASE WHEN quantity >= 188 THEN 'high' WHEN quantity >= 43 THEN 'mid' ELSE 'low' END, store_id) sub WHERE unique_products > 9;
